class PTLRAdamW(torch.optim.AdamW):
    def __init__(self, params, lr=2e-5, kappa=0.02, clip_low=0.1, clip_high=2.0, **kw):
        super().__init__(params, lr=lr, **kw)
        self.kappa = kappa; self.clip_low=clip_low; self.clip_high=clip_high; self.base_lr = lr
    @torch.no_grad()
    def update_lr(self, loss):
        g_dot_d = 0.0
        for g,p in zip([p.grad for p in self.param_groups[0]['params']],
                       [p for p in self.param_groups[0]['params']]):
            if g is None: continue
            # Adam preconditioned direction already stored in p._adam_step
            d = p._adam_step  # patched from optimizer.step()
            g_dot_d += torch.sum(g*d).item()
        lr_star = self.kappa*loss.item() / (abs(g_dot_d)+1e-12)
        lr_star = max(self.clip_low*self.base_lr, min(self.clip_high*self.base_lr, lr_star))
        for g in self.param_groups:
            g['lr'] = lr_star
    def step(self, closure=None):
        loss = closure() if closure is not None else None
        super().step();  # AdamW updates and caches d_t in p._adam_step
        if loss is not None: self.update_lr(loss)
        return loss

class PSTLRAdamW(torch.optim.AdamW):
    def __init__(self, params, lr=2e-5, kappa=0.02, clip_low=0.1, clip_high=3.0, check_prob=0.01, **kw):
        super().__init__(params, lr=lr, **kw)
        self.kappa, self.clip_low, self.clip_high = kappa, clip_low, clip_high
        self.base_lr = lr
        self.prev_grad_dot = None   # stores g_{t-1}·d_{t-1}
        self.prev_dir_sq  = None     # ‖d_{t-1}‖²
        self.prev_lr      = None
        self.check_prob   = check_prob

    @torch.no_grad()
    def _quadratic_lr(self, loss, g_dot_d, dir_sq):
        if self.prev_grad_dot is None:
            return self.kappa*loss/(abs(g_dot_d)+1e-12)
        h_sec = (g_dot_d - self.prev_grad_dot) / ( (self.prev_lr or 1e-20)*(self.prev_dir_sq+1e-12) )
        if h_sec <= 0:  # fallback to first-order
            return self.kappa*loss/(abs(g_dot_d)+1e-12)
        return max(1e-20, -g_dot_d/(h_sec*dir_sq + 1e-12))

    @torch.no_grad()
    def _apply_lr(self, lr_star):
        lr_star = max(self.clip_low*self.base_lr, min(self.clip_high*self.base_lr, lr_star))
        for g in self.param_groups:
            g['lr'] = lr_star
        return lr_star

    def step(self, closure=None):
        if closure is None:
            raise RuntimeError('PST-LR requires closure to obtain fresh loss')
        loss = closure()
        # first AdamW step (stores d_t for every param)
        super().step()

        # gather g·d and ‖d‖² cheaply
        g_dot_d = 0.0; dir_sq = 0.0
        for p in self.param_groups[0]['params']:
            if p.grad is None or not hasattr(p, '_adam_step'): continue
            d = p._adam_step
            g_dot_d += torch.sum(p.grad*d).item()
            dir_sq  += torch.sum(d*d).item()

        lr_star = self._quadratic_lr(loss.item(), g_dot_d, dir_sq)
        lr_used = self._apply_lr(lr_star)

        # probabilistic single minibatch check
        if torch.rand(1).item() < self.check_prob:
            with torch.no_grad():
                check_loss = closure()
            if check_loss > loss:
                for p in self.param_groups[0]['params']:
                    p.data.sub_(p._adam_step*lr_used)  # rollback
                lr_used *= 0.5
                self._apply_lr(lr_used)

        # cache for next step
        self.prev_grad_dot = g_dot_d
        self.prev_dir_sq   = dir_sq
        self.prev_lr       = lr_used
        return loss
